using System.Collections.ObjectModel;
using BenchmarkDotNet.Attributes;
using TextAnalysis;

namespace Benchmarks;

public class TextAnalyzerBenchmarks
{
    private TextAnalyzer _small = null!;
    private TextAnalyzer _large = null!;

    [GlobalSetup]
    public void Setup()
    {
        // Small: ~20 words
        _small = new TextAnalyzer("The quick brown fox jumps over the lazy dog and the cat sat on the mat by the door");

        // Large: ~5000 words built from a repeated base with variation
        var rng = new Random(42);
        var words = new[] { "performance", "benchmark", "analysis", "throughput", "latency",
            "memory", "allocation", "garbage", "collection", "optimization",
            "parallel", "concurrent", "asynchronous", "synchronous", "thread",
            "cache", "pipeline", "register", "instruction", "branch" };
        var parts = new string[5000];
        for (int i = 0; i < parts.Length; i++)
            parts[i] = words[rng.Next(words.Length)];
        _large = new TextAnalyzer(string.Join(" ", parts));
    }

    [Benchmark]
    public double AverageWordLength_Small() => _small.AverageWordLength();

    [Benchmark]
    public double AverageWordLength_Large() => _large.AverageWordLength();

    [Benchmark]
    public ReadOnlyCollection<int> WordLengthHistogram_Small() => _small.WordLengthHistogram();

    [Benchmark]
    public ReadOnlyCollection<int> WordLengthHistogram_Large() => _large.WordLengthHistogram();

    [Benchmark]
    public int UniqueWordCount_Small() => _small.UniqueWordCount();

    [Benchmark]
    public int UniqueWordCount_Large() => _large.UniqueWordCount();
}

